select * from jsonb_to_recordset($FIX$[{"id": "1c616521-2088-4b7d-9d8e-716822eee91b", "ord": 1, "author_id": "10000000-0000-0000-0000-000000000048", "city_id": "vancouver", "title": "\ubd81\uc11c\ud56d\ub85c\ub97c \uac74\ub10c \ubc30\uac00 \ubc34\ucfe0\ubc84 \ubc15\ubb3c\uad00\uc5d0 \ub0a8\uc544 \uc788\ub124", "old_body": "\uc608\uc804\uc5d4 \ud574\uc591\ubc15\ubb3c\uad00\uc774\uba74 \ubc30 \ubaa8\ud615\ubd80\ud130 \ub5a0\uc62c\ub838\ub294\ub370, \ubc34\ucfe0\ubc84\uc5d4 \uc2e4\uc81c \ubd81\uc11c\ud56d\ub85c\ub97c \uac74\ub10c \uc138\uc778\ud2b8\ub85c\ud06c\ud638\uac00 \ub0a8\uc544 \uc788\uc74c\n\ubc30 \uc548\uc758 \uc120\uc2e4\uae4c\uc9c0 \ubcfc \uc218 \uc788\ub294 \uacf3\uc774\ub77c\ub2c8 \uc880 \ub04c\ub9ac\uae34 \ud558\ub294\ub370, \uc5b4\ub290 \uacf5\uac04\ubd80\ud130 \ub4e4\uc5ec\ub2e4\ubcfc\uc9c0\ub294 \uc544\uc9c1 \uc0dd\uac01 \uc911", "new_body": "\uc608\uc804\uc5d4 \ud574\uc591\ubc15\ubb3c\uad00\uc774\uba74 \ubc30 \ubaa8\ud615\ubd80\ud130 \ub5a0\uc62c\ub838\ub294\ub370, \ubc34\ucfe0\ubc84\uc5d4 \uc2e4\uc81c \ubd81\uc11c\ud56d\ub85c\ub97c \uac74\ub10c \uc138\uc778\ud2b8\ub85c\ud06c\ud638\uac00 \ub0a8\uc544 \uc788\uc74c\n\ubc30 \uc548\uc758 \uc120\uc2e4\uae4c\uc9c0 \ubcfc \uc218 \uc788\ub294 \uacf3\uc774\ub77c\ub2c8 \uc880 \ub04c\ub9ac\uae34 \ud558\ub294\ub370, \uc5b4\ub290 \uacf5\uac04\ubd80\ud130 \ub4e4\uc5ec\ub2e4\ubcfc\uc9c0\ub294 \uc544\uc9c1 \uc0dd\uac01 \uc911", "old_created_at": "2026-10-08 05:22:00+00", "new_created_at": "2026-10-08T16:48:24.598103+00:00", "old_pulses": [{"views": 10, "bucket": "2026-10-08T05:20:00+00:00"}]}, {"id": "6c236a06-ff09-40c8-8d1a-8f3523076d15", "ord": 2, "author_id": "10000000-0000-0000-0000-000000000058", "city_id": "vancouver", "title": "\ucc28\uc774\ub098\ud0c0\uc6b4 \uc911\uad6d\uc815\uc6d0\uc774\ub791 \uc606 \uacf5\uc6d0\uc740 \ub2e4\ub978 \uacf5\uac04\uc784", "old_body": "\ucc28\uc774\ub098\ud0c0\uc6b4 \uc815\uc6d0 \uc774\ub984\uc774 \ube44\uc2b7\ud574\uc11c \ub0b4 \uba38\ub9bf\uc18d\uc5d0\uc120 \ud558\ub098\ub85c \ud569\uccd0\ub1a8\uc74c \u314b\u314b \ub450 \uac00\uc9c0 \uc801\uc5b4\ub460\n1) \ub2e5\ud130\uc468\uc58f\uc13c \uc911\uad6d\uc815\uc6d0\uc740 \uba85\ub098\ub77c \uc591\uc2dd\uc758 \uc815\uc6d0\ud615 \ubc15\ubb3c\uad00\uc774\uc57c\n2) \uc606\uc758 \ub2e5\ud130\uc468\uc58f\uc13c \uacf5\uc6d0\uc740 \uc2dc \uacf5\uc6d0\uc704\uc6d0\ud68c\uac00 \uad00\ub9ac\ud558\ub294 \ubcc4\ub3c4 \uacf5\uac04\uc774\ub77c, \uc774\ubc88\uc5d4 \uad6c\ubd84\ud574\uc11c \uae30\uc5b5\ud574\ub450\uba74 \ub35c \ud5f7\uac08\ub9b4 \ub4ef", "new_body": "\ucc28\uc774\ub098\ud0c0\uc6b4 \uc815\uc6d0 \uc774\ub984\uc774 \ube44\uc2b7\ud574\uc11c \ub0b4 \uba38\ub9bf\uc18d\uc5d0\uc120 \ud558\ub098\ub85c \ud569\uccd0\ub1a8\uc74c \u314b\u314b \ub450 \uac00\uc9c0 \uc801\uc5b4\ub460\n1) \ub2e5\ud130\uc468\uc58f\uc13c \uc911\uad6d\uc815\uc6d0\uc740 \uba85\ub098\ub77c \uc591\uc2dd\uc758 \uc815\uc6d0\ud615 \ubc15\ubb3c\uad00\uc774\uc57c\n2) \uc606\uc758 \ub2e5\ud130\uc468\uc58f\uc13c \uacf5\uc6d0\uc740 \uc2dc \uacf5\uc6d0\uc704\uc6d0\ud68c\uac00 \uad00\ub9ac\ud558\ub294 \ubcc4\ub3c4 \uacf5\uac04\uc774\ub77c, \uc774\ubc88\uc5d4 \uad6c\ubd84\ud574\uc11c \uae30\uc5b5\ud574\ub450\uba74 \ub35c \ud5f7\uac08\ub9b4 \ub4ef", "old_created_at": "2026-10-08 01:52:00+00", "new_created_at": "2026-10-08T16:38:23.598103+00:00", "old_pulses": [{"views": 9, "bucket": "2026-10-08T01:50:00+00:00"}]}, {"id": "db0305f8-a88b-417f-b857-acc86c9fdec5", "ord": 3, "author_id": "10000000-0000-0000-0000-000000000051", "city_id": "vancouver", "title": "MOA \uadf8\ub808\uc774\ud2b8\ud640\uc5d4 \ucee4\ub2e4\ub780 \uae30\ub465 \uc870\uac01\ub3c4 \uc788\ub124", "old_body": "\uc870\uac01 \uc55e\uc5d0\uc11c \uc624\ub798 \uba48\ucd94\ub294 \uc0ac\ub78c \ub9c8\uc74c\uc774 \uc870\uae08\uc740 \uc774\ud574\ub420 \uac83 \uac19\uc544\uc11c MOA \uadf8\ub808\uc774\ud2b8\ud640 \ucc98\uc74c \uc54c\uc544\ubd04\n\ud070 \uae30\ub465 \uc870\uac01\uacfc \uc9d1 \uae30\ub465, \uc870\uac01\uc0c1\uc774 \uc788\uace0 \ud604\ub300 \uc791\uac00\uc758 \uc791\ud488\ub3c4 \ud568\uaed8 \ub193\uc5ec \uc788\ub124\n\ub09c \uc791\ud488 \uc774\ub984\ub9cc \uc678\uc6b0\uae30\ubcf4\ub2e4 \uac19\uc740 \uacf5\uac04\uc5d0 \ub193\uc778 \uc61b \uc791\uc5c5\uacfc \uc9c0\uae08 \uc791\uc5c5\ubd80\ud130 \ub098\ub780\ud788 \ubcfc \uac70\uc57c", "new_body": "\uc870\uac01 \uc55e\uc5d0\uc11c \uc624\ub798 \uba48\ucd94\ub294 \uc0ac\ub78c \ub9c8\uc74c\uc774 \uc870\uae08\uc740 \uc774\ud574\ub420 \uac83 \uac19\uc544\uc11c MOA \uadf8\ub808\uc774\ud2b8\ud640 \ucc98\uc74c \uc54c\uc544\ubd04\n\ud070 \uae30\ub465 \uc870\uac01\uacfc \uc9d1 \uae30\ub465, \uc870\uac01\uc0c1\uc774 \uc788\uace0 \ud604\ub300 \uc791\uac00\uc758 \uc791\ud488\ub3c4 \ud568\uaed8 \ub193\uc5ec \uc788\ub124\n\ub09c \uc791\ud488 \uc774\ub984\ub9cc \uc678\uc6b0\uae30\ubcf4\ub2e4 \uac19\uc740 \uacf5\uac04\uc5d0 \ub193\uc778 \uc61b \uc791\uc5c5\uacfc \uc9c0\uae08 \uc791\uc5c5\ubd80\ud130 \ub098\ub780\ud788 \ubcfc \uac70\uc57c", "old_created_at": "2026-10-08 06:49:00+00", "new_created_at": "2026-10-08T16:28:22.598103+00:00", "old_pulses": [{"views": 6, "bucket": "2026-10-08T06:40:00+00:00"}]}, {"id": "18b006c4-b198-4eb6-82a7-371b3f2620cd", "ord": 4, "author_id": "10000000-0000-0000-0000-000000000025", "city_id": "vancouver", "title": "UBC \ud770\uc218\uc5fc\uace0\ub798 \ubf08, \ub2e4\ub978 \ud574\uc548\uc5d0\uc11c \uc628 \ud45c\ubcf8\uc774\uc5c8\ub124", "old_body": "\ucc45\uc5d0\uc11c\ub294 \uace0\ub798\ub97c \uadf8\ub9bc\uc73c\ub85c \uba3c\uc800 \ubcf4\uace4 \ud588\ub294\ub370\nUBC \ube44\ud2f0\uc0dd\ubb3c\ub2e4\uc591\uc131\ubc15\ubb3c\uad00\uc5d4 \ud770\uc218\uc5fc\uace0\ub798 \uace8\uaca9\uc774 \uc804\uc2dc\ub3fc \uc788\ub124\n\ud504\ub9b0\uc2a4\uc5d0\ub4dc\uc6cc\ub4dc\uc544\uc77c\ub79c\ub4dc \ud574\uc548\uc5d0\uc11c \ubc1c\uacac\ub41c \uace0\ub798\uac00 \ubc34\ucfe0\ubc84\uae4c\uc9c0 \uc628 \uac70\uc57c\n\ud45c\ubcf8\uc744 \uc62e\uae30\uace0 \uc804\uc2dc\ud558\uae30\uae4c\uc9c0\uc758 \uacfc\uc815\uc744 \ub2f4\uc740 \ub2e4\ud050\uba58\ud130\ub9ac\ub3c4 \uc788\uace0\n\ub098\ub294 \ub3d9\ubb3c \uc774\ub984\ubcf4\ub2e4 \uc774 \ud45c\ubcf8\uc774 \uc5ec\uae30 \ub0a8\uac8c \ub41c \uc774\uc57c\uae30\ubd80\ud130 \ucc9c\ucc9c\ud788 \uc54c\uc544\ubcfc\uae4c \ud574", "new_body": "\ucc45\uc5d0\uc11c\ub294 \uace0\ub798\ub97c \uadf8\ub9bc\uc73c\ub85c \uba3c\uc800 \ubcf4\uace4 \ud588\ub294\ub370\nUBC \ube44\ud2f0\uc0dd\ubb3c\ub2e4\uc591\uc131\ubc15\ubb3c\uad00\uc5d4 \ud770\uc218\uc5fc\uace0\ub798 \uace8\uaca9\uc774 \uc804\uc2dc\ub3fc \uc788\ub124\n\ud504\ub9b0\uc2a4\uc5d0\ub4dc\uc6cc\ub4dc\uc544\uc77c\ub79c\ub4dc \ud574\uc548\uc5d0\uc11c \ubc1c\uacac\ub41c \uace0\ub798\uac00 \ubc34\ucfe0\ubc84\uae4c\uc9c0 \uc628 \uac70\uc57c\n\ud45c\ubcf8\uc744 \uc62e\uae30\uace0 \uc804\uc2dc\ud558\uae30\uae4c\uc9c0\uc758 \uacfc\uc815\uc744 \ub2f4\uc740 \ub2e4\ud050\uba58\ud130\ub9ac\ub3c4 \uc788\uace0\n\ub098\ub294 \ub3d9\ubb3c \uc774\ub984\ubcf4\ub2e4 \uc774 \ud45c\ubcf8\uc774 \uc5ec\uae30 \ub0a8\uac8c \ub41c \uc774\uc57c\uae30\ubd80\ud130 \ucc9c\ucc9c\ud788 \uc54c\uc544\ubcfc\uae4c \ud574", "old_created_at": "2026-10-08 06:33:00+00", "new_created_at": "2026-10-08T16:18:21.598103+00:00", "old_pulses": [{"views": 5, "bucket": "2026-10-08T06:30:00+00:00"}]}, {"id": "4c2290ea-607d-468d-ba8d-b0a3140a11a2", "ord": 5, "author_id": "10000000-0000-0000-0000-000000000066", "city_id": "vancouver", "title": "\uc6e8\uc2a4\ud2b8\ucf54\uc2a4\ud2b8\uc775\uc2a4\ud504\ub808\uc2a4\ub294 \uc544\uce68\uacfc \uc800\ub141 \ubc29\ud5a5\uc774 \ub2e4\ub984", "old_body": "\ucd9c\uadfc\ud558\ub294 \uc0ac\ub78c\ub4e4 \ub3d9\uc120\uc740 \uac19\uc740 \uc5f4\ucc28\ub77c\ub3c4 \uc2dc\uac04\ub300 \ub530\ub77c \ubc29\ud5a5\uc774 \uc644\uc804\ud788 \ub2e4\ub974\ub124\n\uc6e8\uc2a4\ud2b8\ucf54\uc2a4\ud2b8\uc775\uc2a4\ud504\ub808\uc2a4\ub294 \ubc34\ucfe0\ubc84 \ub2e4\uc6b4\ud0c0\uc6b4\uacfc \ubbf8\uc158\uc2dc\ud2f0\ub97c \uc787\ub294 \ud1b5\uadfc\uc5f4\ucc28\uc57c\n\ud3c9\uc77c \uc544\uce68\uc5d4 \ubc34\ucfe0\ubc84 \ucabd, \uc624\ud6c4\u00b7\uc800\ub141\uc5d4 \ubbf8\uc158 \ucabd\uc73c\ub85c\ub9cc \uac00\ub294 \uad6c\uc870\uace0\n\uc6b4\ud589 \uc548\ub0b4\ub294 \ubc14\ub014 \uc218 \uc788\uc73c\ub2c8 \uc2e4\uc81c \ud0c0\uae30 \uc804\uc5d4 \ub2e4\uc2dc \ud655\uc778\ud574\n\ub09c \uc9c0\ub3c4\uc5d0 \uc120 \ud558\ub098 \uae0b\ub294 \ub370\uc11c \ub05d\ub0b4\uc9c0 \uc54a\uace0 \ubc29\ud5a5\uae4c\uc9c0 \uac19\uc774 \ub123\uc744 \uac70\uc57c", "new_body": "\ucd9c\uadfc\ud558\ub294 \uc0ac\ub78c\ub4e4 \ub3d9\uc120\uc740 \uac19\uc740 \uc5f4\ucc28\ub77c\ub3c4 \uc2dc\uac04\ub300 \ub530\ub77c \ubc29\ud5a5\uc774 \uc644\uc804\ud788 \ub2e4\ub974\ub124\n\uc6e8\uc2a4\ud2b8\ucf54\uc2a4\ud2b8\uc775\uc2a4\ud504\ub808\uc2a4\ub294 \ubc34\ucfe0\ubc84 \ub2e4\uc6b4\ud0c0\uc6b4\uacfc \ubbf8\uc158\uc2dc\ud2f0\ub97c \uc787\ub294 \ud1b5\uadfc\uc5f4\ucc28\uc57c\n\ud3c9\uc77c \uc544\uce68\uc5d4 \ubc34\ucfe0\ubc84 \ucabd, \uc624\ud6c4\u00b7\uc800\ub141\uc5d4 \ubbf8\uc158 \ucabd\uc73c\ub85c\ub9cc \uac00\ub294 \uad6c\uc870\uace0\n\uc6b4\ud589 \uc548\ub0b4\ub294 \ubc14\ub014 \uc218 \uc788\uc73c\ub2c8 \uc2e4\uc81c \ud0c0\uae30 \uc804\uc5d4 \ub2e4\uc2dc \ud655\uc778\ud574\n\ub09c \uc9c0\ub3c4\uc5d0 \uc120 \ud558\ub098 \uae0b\ub294 \ub370\uc11c \ub05d\ub0b4\uc9c0 \uc54a\uace0 \ubc29\ud5a5\uae4c\uc9c0 \uac19\uc774 \ub123\uc744 \uac70\uc57c", "old_created_at": "2026-10-07 19:10:00+00", "new_created_at": "2026-10-08T16:08:20.598103+00:00", "old_pulses": [{"views": 1, "bucket": "2026-10-07T19:10:00+00:00"}]}, {"id": "cc6533d7-3fae-4922-9a74-c71d2d703a9d", "ord": 6, "author_id": "10000000-0000-0000-0000-000000000031", "city_id": "toronto", "title": "\ub9ac\ubc84\ub370\uc77c\ub18d\uc7a5 \uc678\uc591\uac04\uc740 \uc5b8\ub355\uc744 \uc774\uc6a9\ud574 \uc9c0\uc740 \uac74\ubb3c\uc774\ub798", "old_body": "\uc678\uc591\uac04\ub3c4 \uadf8\ub0e5 \ud3c9\uc9c0\uc5d0 \uc138\uc6b4 \uac74\ubb3c\uc778 \uc904 \uc54c\uc558\ub294\ub370, \ub9ac\ubc84\ub370\uc77c\ub18d\uc7a5\uc758 \ud504\ub79c\uc2dc\ubc18\uc740 \uc5b8\ub355\uc744 \uc774\uc6a9\ud55c \uad6c\uc870\uc57c\n\uc544\ub798\uce35\uc740 \ub3d9\ubb3c \uacf5\uac04\uc774\uace0 \uc704\uce35\uc740 \uac74\ucd08 \uc800\uc7a5 \uacf5\uac04\uc778\ub370 \ub458 \ub2e4 \ub545\uc5d0\uc11c \ub4dc\ub098\ub4e4 \uc218 \uc788\uc74c, \ub0b4 \uac74\ubb3c \uc0c1\uc0c1\ub825\uc774 \ub108\ubb34 \ub0a9\uc791\ud588\ub124 \u314b\u314b", "new_body": "\uc678\uc591\uac04\ub3c4 \uadf8\ub0e5 \ud3c9\uc9c0\uc5d0 \uc138\uc6b4 \uac74\ubb3c\uc778 \uc904 \uc54c\uc558\ub294\ub370, \ub9ac\ubc84\ub370\uc77c\ub18d\uc7a5\uc758 \ud504\ub79c\uc2dc\ubc18\uc740 \uc5b8\ub355\uc744 \uc774\uc6a9\ud55c \uad6c\uc870\uc57c\n\uc544\ub798\uce35\uc740 \ub3d9\ubb3c \uacf5\uac04\uc774\uace0 \uc704\uce35\uc740 \uac74\ucd08 \uc800\uc7a5 \uacf5\uac04\uc778\ub370 \ub458 \ub2e4 \ub545\uc5d0\uc11c \ub4dc\ub098\ub4e4 \uc218 \uc788\uc74c, \ub0b4 \uac74\ubb3c \uc0c1\uc0c1\ub825\uc774 \ub108\ubb34 \ub0a9\uc791\ud588\ub124 \u314b\u314b", "old_created_at": "2026-10-07 22:56:00+00", "new_created_at": "2026-10-08T15:58:19.598103+00:00", "old_pulses": [{"views": 19, "bucket": "2026-10-07T22:50:00+00:00"}]}, {"id": "52ad14cd-2c75-43b6-93b9-02176ae8d155", "ord": 7, "author_id": "10000000-0000-0000-0000-000000000033", "city_id": "toronto", "title": "\uc288\uac00\ube44\uce58 \ubd84\ud64d \ud30c\ub77c\uc194 \uc790\ub9ac, \uc6d0\ub798\ub294 \uc8fc\ucc28\uc7a5\uc774\uc5c8\ub300", "old_body": "\ubb3c\uac00\uc5d0\uc11c \uc26c\ub294 \uc0ac\ub78c\ub4e4 \uc0ac\uc9c4 \ubcf4\uba74 \ubaa8\ub798\ub294 \uc6d0\ub798 \uc788\ub358 \uc904 \uc54c\uc558\uc74c\n\ud1a0\ub860\ud1a0 \uc288\uac00\ube44\uce58\ub294 \uc61b \uc0b0\uc5c5 \uc9c0\uc5ed\uc758 \uc9c0\uc0c1 \uc8fc\ucc28\uc7a5\uc744 \ubc14\uafbc \uacf5\uac04\uc774\uace0, \ubd84\ud64d \ud30c\ub77c\uc194\uc774 \ud2b9\uc9d5\uc774\ub124\n\uc774\ub984\ub9cc \ubcf4\uace0 \uc218\uc601\uc7a5\ucc98\ub7fc \uc0dd\uac01\ud55c \ub0b4 \uc0c1\uc0c1\uc740 \uc7a0\uae50 \uc811\uace0, \uac19\uc774 \uac77\uac8c \ub418\uba74 \uadf8 \uc790\ub9ac\uc758 \uc61b \ubaa8\uc2b5\ubd80\ud130 \uc598\uae30\ud574\ubcfc\uae4c \ud574", "new_body": "\ubb3c\uac00\uc5d0\uc11c \uc26c\ub294 \uc0ac\ub78c\ub4e4 \uc0ac\uc9c4 \ubcf4\uba74 \ubaa8\ub798\ub294 \uc6d0\ub798 \uc788\ub358 \uc904 \uc54c\uc558\uc74c\n\ud1a0\ub860\ud1a0 \uc288\uac00\ube44\uce58\ub294 \uc61b \uc0b0\uc5c5 \uc9c0\uc5ed\uc758 \uc9c0\uc0c1 \uc8fc\ucc28\uc7a5\uc744 \ubc14\uafbc \uacf5\uac04\uc774\uace0, \ubd84\ud64d \ud30c\ub77c\uc194\uc774 \ud2b9\uc9d5\uc774\ub124\n\uc774\ub984\ub9cc \ubcf4\uace0 \uc218\uc601\uc7a5\ucc98\ub7fc \uc0dd\uac01\ud55c \ub0b4 \uc0c1\uc0c1\uc740 \uc7a0\uae50 \uc811\uace0, \uac19\uc774 \uac77\uac8c \ub418\uba74 \uadf8 \uc790\ub9ac\uc758 \uc61b \ubaa8\uc2b5\ubd80\ud130 \uc598\uae30\ud574\ubcfc\uae4c \ud574", "old_created_at": "2026-10-07 23:58:00+00", "new_created_at": "2026-10-08T15:48:18.598103+00:00", "old_pulses": [{"views": 1, "bucket": "2026-10-07T23:50:00+00:00"}]}, {"id": "3351042a-7ca7-41ff-8412-389deb84b8fb", "ord": 9, "author_id": "10000000-0000-0000-0000-000000000036", "city_id": "toronto", "title": "TPL \uc624\uc988\ubc88 \uceec\ub809\uc158\uc740 \uc5b4\ub9b0\uc774\ucc45\uc758 \ud754\uc801\uae4c\uc9c0 \ubaa8\uc544\ub450\ub124", "old_body": "\uc5b4\ub9b0\uc774\ucc45\uc744 \ub2e4\uc2dc \ud3bc\uce58\uba74 \ub0b4\uc6a9\ubcf4\ub2e4 \uadf8\ub54c\uc758 \uae30\ubd84\uc774 \uba3c\uc800 \ub5a0\uc624\ub97c \uac83 \uac19\uc544\nTPL \uc624\uc988\ubc88 \uceec\ub809\uc158\uc740 \uc624\ub798\ub418\uace0 \ud2b9\ubcc4\ud55c \uc5b4\ub9b0\uc774\ucc45\uc744 \ubaa8\uc544\ub454 \uc5f0\uad6c \uceec\ub809\uc158\uc774\ub124\n\ucc45\ubfd0 \uc544\ub2c8\ub77c \uad00\ub828 \uadf8\ub9bc\u00b7\uc7a5\ub09c\uac10\u00b7\uac8c\uc784\uacfc \uae30\ub85d\ubb3c\ub3c4 \ud568\uaed8 \ub2e4\ub8e8\uace0\n\ub098\ub294 \uc77d\uc744 \ucc45\ubd80\ud130 \uc815\ud558\uae30\ubcf4\ub2e8 \uc5b4\ub5a4 \ud754\uc801\uc774 \ub0a8\uc544 \uc788\ub294\uc9c0 \ucc9c\ucc9c\ud788 \uc54c\uc544\ubcf4\uace0 \uc2f6\uc740\ub370\n\uc5b4\ub9b4 \ub54c \uc77d\ub358 \ucc45\uc740 \uc904\uac70\ub9ac\ub791 \uadf8\ub9bc \uc911 \ubb50\uac00 \uba3c\uc800 \uc0dd\uac01\ub098?", "new_body": "\uc5b4\ub9b0\uc774\ucc45\uc744 \ub2e4\uc2dc \ud3bc\uce58\uba74 \ub0b4\uc6a9\ubcf4\ub2e4 \uadf8\ub54c\uc758 \uae30\ubd84\uc774 \uba3c\uc800 \ub5a0\uc624\ub97c \uac83 \uac19\uc544\nTPL \uc624\uc988\ubc88 \uceec\ub809\uc158\uc740 \uc624\ub798\ub418\uace0 \ud2b9\ubcc4\ud55c \uc5b4\ub9b0\uc774\ucc45\uc744 \ubaa8\uc544\ub454 \uc5f0\uad6c \uceec\ub809\uc158\uc774\ub124\n\ucc45\ubfd0 \uc544\ub2c8\ub77c \uad00\ub828 \uadf8\ub9bc\u00b7\uc7a5\ub09c\uac10\u00b7\uac8c\uc784\uacfc \uae30\ub85d\ubb3c\ub3c4 \ud568\uaed8 \ub2e4\ub8e8\uace0\n\ub098\ub294 \uc77d\uc744 \ucc45\ubd80\ud130 \uc815\ud558\uae30\ubcf4\ub2e8 \uc5b4\ub5a4 \ud754\uc801\uc774 \ub0a8\uc544 \uc788\ub294\uc9c0 \ucc9c\ucc9c\ud788 \uc54c\uc544\ubcf4\uace0 \uc2f6\uc740\ub370\n\uc5b4\ub9b4 \ub54c \uc77d\ub358 \ucc45\uc740 \uc904\uac70\ub9ac\ub791 \uadf8\ub9bc \uc911 \ubb50\uac00 \uba3c\uc800 \uc0dd\uac01\ub098?", "old_created_at": "2026-10-07 17:53:00+00", "new_created_at": "2026-10-08T15:28:16.598103+00:00", "old_pulses": [{"views": 5, "bucket": "2026-10-07T17:50:00+00:00"}]}, {"id": "5007adfb-05b1-4c55-a839-5c4c72a058c2", "ord": 10, "author_id": "08db325f-9c20-537a-8e88-4418cecf447b", "city_id": "toronto", "title": "\ucf54\ud06c\ud0c0\uc6b4\ucee4\uba3c\uc740 \ud64d\uc218 \ub9c9\ub294 \uc9c0\ud615 \uc704\uc5d0 \ub193\uc778 \uacf5\uc6d0\uc774\ub124", "old_body": "\uacf5\uc6d0\ub3c4 \uc26c\ub294 \uc7a5\uc18c \ub9d0\uace0 \ud558\ub294 \uc77c\uc774 \ub354 \uc788\ub2e4\ub294 \uac8c \uc880 \ub4e0\ub4e0\ud574\uc11c \uc801\uc5b4\ubd04\n1) \ucf54\ud06c\ud0c0\uc6b4\ucee4\uba3c\uc740 \ud64d\uc218\ub97c \ub9c9\ub294 \uc9c0\ud615 \uc704\uc5d0 \ub9cc\ub4e0 \uacf5\uc6d0\uc774\uc57c\n2) \uc548\uc758 \uc2b5\uc9c0\ub294 \ube57\ubb3c \uad00\ub9ac\uc5d0 \uc4f0\uc774\uba74\uc11c \uc0c8\u00b7\uace4\ucda9\u00b7\uac1c\uad6c\ub9ac\uc758 \uc11c\uc2dd\uc9c0\uac00 \ub418\uace0\n3) \uc794\ub514 \uacf5\uac04\uc774\ub791 \uc0b0\ucc45\uae38\ub3c4 \uc774 \uc9c0\ud615\uc5d0 \ub9de\ucdb0 \uc124\uacc4\ub41c \uac70\ub124\n\ub09c \ucc98\uc74c\ubd80\ud130 \ucf54\uc2a4\ub97c \ud06c\uac8c \uc7a1\uae30\ubcf4\ub2e4 \uc774\ub7f0 \uc5ed\ud560\uc774 \ubcf4\uc774\ub294 \uc790\ub9ac \ud558\ub098\ubd80\ud130 \uace8\ub77c\ubcfc \uac70\uc57c", "new_body": "\uacf5\uc6d0\ub3c4 \uc26c\ub294 \uc7a5\uc18c \ub9d0\uace0 \ud558\ub294 \uc77c\uc774 \ub354 \uc788\ub2e4\ub294 \uac8c \uc880 \ub4e0\ub4e0\ud574\uc11c \uc801\uc5b4\ubd04\n1) \ucf54\ud06c\ud0c0\uc6b4\ucee4\uba3c\uc740 \ud64d\uc218\ub97c \ub9c9\ub294 \uc9c0\ud615 \uc704\uc5d0 \ub9cc\ub4e0 \uacf5\uc6d0\uc774\uc57c\n2) \uc548\uc758 \uc2b5\uc9c0\ub294 \ube57\ubb3c \uad00\ub9ac\uc5d0 \uc4f0\uc774\uba74\uc11c \uc0c8\u00b7\uace4\ucda9\u00b7\uac1c\uad6c\ub9ac\uc758 \uc11c\uc2dd\uc9c0\uac00 \ub418\uace0\n3) \uc794\ub514 \uacf5\uac04\uc774\ub791 \uc0b0\ucc45\uae38\ub3c4 \uc774 \uc9c0\ud615\uc5d0 \ub9de\ucdb0 \uc124\uacc4\ub41c \uac70\ub124\n\ub09c \ucc98\uc74c\ubd80\ud130 \ucf54\uc2a4\ub97c \ud06c\uac8c \uc7a1\uae30\ubcf4\ub2e4 \uc774\ub7f0 \uc5ed\ud560\uc774 \ubcf4\uc774\ub294 \uc790\ub9ac \ud558\ub098\ubd80\ud130 \uace8\ub77c\ubcfc \uac70\uc57c", "old_created_at": "2026-10-07 23:36:00+00", "new_created_at": "2026-10-08T15:18:15.598103+00:00", "old_pulses": [{"views": 11, "bucket": "2026-10-07T23:30:00+00:00"}]}, {"id": "5c0d4bc4-fb02-47eb-93ab-451d7043d187", "ord": 11, "author_id": "3af69d3c-ebe8-5e33-9f8c-e62a1abc7e24", "city_id": "montreal", "title": "\ub808\ub4dc\ud328\uc2a4\ubc15\ubb3c\uad00\uc740 \uc554\uc11d\uc774\ub791 \ub3d9\ubb3c \ud45c\ubcf8\uc744 \uac19\uc774 \ubaa8\uc544\ub450\ub124", "old_body": "\uc790\uc5f0\uc0ac \uad6c\uacbd\ud558\ub294 \uc0ac\ub78c\uc740 \ud070 \ub3d9\ubb3c \ubf08\ub9cc \ubcfc \uc904 \uc54c\uc558\ub294\ub370, \ub9e5\uae38 \ub808\ub4dc\ud328\uc2a4\ubc15\ubb3c\uad00 \uceec\ub809\uc158\uc5d4 \uace0\uc0dd\ubb3c\u00b7\uc554\uc11d\u00b7\uad11\ubb3c\u00b7\ub3d9\ubb3c \uc790\ub8cc\uac00 \ub098\ub258\uc5b4 \uc788\ub124\n\ub3cc\uba69\uc774 \uc55e\uc5d0\uc11c\ub3c4 \ud560 \uc598\uae30\uac00 \uc774\ub807\uac8c \ub9ce\ub2e4\ub2c8 \uc880 \uc2e0\ub0a8, \ub0b4\uac00 \uadf8\ub0e5 \ub3cc\uc774\ub77c\uace0 \ubd80\ub978 \uac83\ub4e4\ud55c\ud14c \ubbf8\uc548\ud574\uc9c8 \ub4ef \u314b\u314b", "new_body": "\uc790\uc5f0\uc0ac \uad6c\uacbd\ud558\ub294 \uc0ac\ub78c\uc740 \ud070 \ub3d9\ubb3c \ubf08\ub9cc \ubcfc \uc904 \uc54c\uc558\ub294\ub370, \ub9e5\uae38 \ub808\ub4dc\ud328\uc2a4\ubc15\ubb3c\uad00 \uceec\ub809\uc158\uc5d4 \uace0\uc0dd\ubb3c\u00b7\uc554\uc11d\u00b7\uad11\ubb3c\u00b7\ub3d9\ubb3c \uc790\ub8cc\uac00 \ub098\ub258\uc5b4 \uc788\ub124\n\ub3cc\uba69\uc774 \uc55e\uc5d0\uc11c\ub3c4 \ud560 \uc598\uae30\uac00 \uc774\ub807\uac8c \ub9ce\ub2e4\ub2c8 \uc880 \uc2e0\ub0a8, \ub0b4\uac00 \uadf8\ub0e5 \ub3cc\uc774\ub77c\uace0 \ubd80\ub978 \uac83\ub4e4\ud55c\ud14c \ubbf8\uc548\ud574\uc9c8 \ub4ef \u314b\u314b", "old_created_at": "2026-10-07 22:58:00+00", "new_created_at": "2026-10-08T15:08:14.598103+00:00", "old_pulses": [{"views": 14, "bucket": "2026-10-07T22:50:00+00:00"}]}, {"id": "dbc9465b-46f3-4732-9211-2f6009b7295f", "ord": 15, "author_id": "cc3ea647-6ac1-5ffc-ba83-8d4724d2e0f1", "city_id": "montreal", "title": "\ubaac\ud2b8\ub9ac\uc62c \uacfc\ud559\uc13c\ud130 \ud734\uba3c\uc740 \ubab8\uc758 \ubcc0\ud654\ub97c \uc9c1\uc811 \uc0b4\ud3b4\ubcf4\ub294 \uc804\uc2dc\uc57c", "old_body": "\ubc15\ubb3c\uad00\uc5d0\uc11c \ubab8\uc744 \ubc30\uc6b0\ub294 \uac74 \uadf8\ub9bc \uc124\uba85 \uc77d\ub294 \uc77c\ub9cc\uc740 \uc544\ub2c8\ub124\n\ubaac\ud2b8\ub9ac\uc62c \uacfc\ud559\uc13c\ud130 \ud734\uba3c\uc740 \uc0b6\uc758 \ub2e8\uacc4\ub9c8\ub2e4 \ubab8\uc774 \uc5b4\ub5bb\uac8c \ubcc0\ud558\ub294\uc9c0 \ub2e4\ub8e8\ub294 \uc804\uc2dc\uc57c\n\uc6c0\uc9c1\uc774\uace0 \ub9cc\uc9c0\uace0 \uc790\uc804\uac70\ub97c \ud0c0\ub294 \ud65c\ub3d9\uc774\ub098 \ub2e4\ub978 \uace8\uaca9\uacfc \ube44\uad50\ud558\ub294 \ud65c\ub3d9\uc774 \uc788\uace0\n\ub85c\ubd07 \ud314\uacfc \uc0ac\ub78c\u00b7\uae30\uacc4\uc758 \uc5f0\uacb0\uc744 \uc0b4\ud3b4\ubcf4\ub294 \ucabd\ub3c4 \uac19\uc774 \ub193\uc5ec \uc788\uc5b4\n\ubab8\uc744 \ubc30\uc6b0\ub294 \uccb4\ud5d8\uc774\ub77c\uba74 \uc6c0\uc9c1\uc784\uc774\ub791 \uace8\uaca9 \uc911 \uc5b4\ub290 \ucabd\uc774 \ub354 \uad81\uae08\ud574?", "new_body": "\ubc15\ubb3c\uad00\uc5d0\uc11c \ubab8\uc744 \ubc30\uc6b0\ub294 \uac74 \uadf8\ub9bc \uc124\uba85 \uc77d\ub294 \uc77c\ub9cc\uc740 \uc544\ub2c8\ub124\n\ubaac\ud2b8\ub9ac\uc62c \uacfc\ud559\uc13c\ud130 \ud734\uba3c\uc740 \uc0b6\uc758 \ub2e8\uacc4\ub9c8\ub2e4 \ubab8\uc774 \uc5b4\ub5bb\uac8c \ubcc0\ud558\ub294\uc9c0 \ub2e4\ub8e8\ub294 \uc804\uc2dc\uc57c\n\uc6c0\uc9c1\uc774\uace0 \ub9cc\uc9c0\uace0 \uc790\uc804\uac70\ub97c \ud0c0\ub294 \ud65c\ub3d9\uc774\ub098 \ub2e4\ub978 \uace8\uaca9\uacfc \ube44\uad50\ud558\ub294 \ud65c\ub3d9\uc774 \uc788\uace0\n\ub85c\ubd07 \ud314\uacfc \uc0ac\ub78c\u00b7\uae30\uacc4\uc758 \uc5f0\uacb0\uc744 \uc0b4\ud3b4\ubcf4\ub294 \ucabd\ub3c4 \uac19\uc774 \ub193\uc5ec \uc788\uc5b4\n\ubab8\uc744 \ubc30\uc6b0\ub294 \uccb4\ud5d8\uc774\ub77c\uba74 \uc6c0\uc9c1\uc784\uc774\ub791 \uace8\uaca9 \uc911 \uc5b4\ub290 \ucabd\uc774 \ub354 \uad81\uae08\ud574?", "old_created_at": "2026-10-08 02:04:00+00", "new_created_at": "2026-10-08T14:28:10.598103+00:00", "old_pulses": [{"views": 6, "bucket": "2026-10-08T02:00:00+00:00"}]}, {"id": "a7048d96-69c5-4bb4-b4f9-2bbc1d21ed25", "ord": 16, "author_id": "10000000-0000-0000-0000-000000000111", "city_id": "edmonton", "title": "\uc5d0\ub4dc\uba3c\ud134 LRT\uc5ed\uc740 \ubc84\uc2a4 \ud658\uc2b9 \uacf5\uac04\uacfc\ub3c4 \uc774\uc5b4\uc9c0\ub124", "old_body": "\ub178\uc120\ub9cc \ubcf4\ub294 \uac83\ubcf4\ub2e4 \uc5ed \uc8fc\ubcc0 \uc5f0\uacb0\ub3c4 \uac19\uc774 \uc54c\uc544\ub450\ub294 \uc911\uc784, 1) \uc5d0\ub4dc\uba3c\ud134 LRT \uc815\ub958\uc7a5\u00b7\uc5ed\uc740 \uc2dc \uc548 \uc5ec\ub7ec \uacf3\uc5d0 \uc788\uace0\n2) \uc5ec\ub7ec \uc5ed\uc774 \ud2b8\ub79c\uc9d3\uc13c\ud130\uc640 \uc774\uc5b4\uc838 \ubc84\uc2a4\ub85c \uac08\uc544\ud0c8 \uc218 \uc788\uc73c\ub2c8, \ub098\ub294 \uac00\uae4c\uc6b4 \uc5ed \ud558\ub098\ubd80\ud130 \uc0b4\ud3b4\ubcfc\uae4c \ud568", "new_body": "\ub178\uc120\ub9cc \ubcf4\ub294 \uac83\ubcf4\ub2e4 \uc5ed \uc8fc\ubcc0 \uc5f0\uacb0\ub3c4 \uac19\uc774 \uc54c\uc544\ub450\ub294 \uc911\uc784, 1) \uc5d0\ub4dc\uba3c\ud134 LRT \uc815\ub958\uc7a5\u00b7\uc5ed\uc740 \uc2dc \uc548 \uc5ec\ub7ec \uacf3\uc5d0 \uc788\uace0\n2) \uc5ec\ub7ec \uc5ed\uc774 \ud2b8\ub79c\uc9d3\uc13c\ud130\uc640 \uc774\uc5b4\uc838 \ubc84\uc2a4\ub85c \uac08\uc544\ud0c8 \uc218 \uc788\uc73c\ub2c8, \ub098\ub294 \uac00\uae4c\uc6b4 \uc5ed \ud558\ub098\ubd80\ud130 \uc0b4\ud3b4\ubcfc\uae4c \ud568", "old_created_at": "2026-10-08 05:09:00+00", "new_created_at": "2026-10-08T14:18:09.598103+00:00", "old_pulses": [{"views": 6, "bucket": "2026-10-08T05:00:00+00:00"}]}, {"id": "9fee67e4-c912-4500-aad9-7d0349e956fa", "ord": 17, "author_id": "e64f591a-676e-5778-8a10-fc892105f91c", "city_id": "edmonton", "title": "\ud654\uc774\ud2b8\uba38\ub4dc\ud30c\ud06c\uc5d4 \ub9d0\uc774 \ub2e4\ub2c8\ub294 \uc9c0\uc815 \uae38\ub3c4 \uc788\ub124", "old_body": "\uac15\ubcc0 \uac77\ub294 \uc0ac\ub78c\uacfc \uc790\uc804\uac70 \ud0c0\ub294 \uc0ac\ub78c\ub9cc \ub5a0\uc62c\ub838\ub294\ub370, \ud654\uc774\ud2b8\uba38\ub4dc\ud30c\ud06c\uc5d4 \uc2b9\ub9c8\uc6a9\uc73c\ub85c \uc9c0\uc815\ud55c \uae38\ub3c4 \uc788\ub124\n\uc608\uc804\uc5d4 \uacf5\uc6d0 \uae38\uc740 \ub2e4 \uac19\uc740 \uc904 \uc54c\uc558\uc74c, \ub0b4 \uc0b0\ucc45 \uc9c0\ub3c4\uc5d0 \ub9d0 \uadf8\ub9bc\ub3c4 \ub4e4\uc5b4\uac00\uc57c\uaca0\uad70 \u314b\u314b", "new_body": "\uac15\ubcc0 \uac77\ub294 \uc0ac\ub78c\uacfc \uc790\uc804\uac70 \ud0c0\ub294 \uc0ac\ub78c\ub9cc \ub5a0\uc62c\ub838\ub294\ub370, \ud654\uc774\ud2b8\uba38\ub4dc\ud30c\ud06c\uc5d4 \uc2b9\ub9c8\uc6a9\uc73c\ub85c \uc9c0\uc815\ud55c \uae38\ub3c4 \uc788\ub124\n\uc608\uc804\uc5d4 \uacf5\uc6d0 \uae38\uc740 \ub2e4 \uac19\uc740 \uc904 \uc54c\uc558\uc74c, \ub0b4 \uc0b0\ucc45 \uc9c0\ub3c4\uc5d0 \ub9d0 \uadf8\ub9bc\ub3c4 \ub4e4\uc5b4\uac00\uc57c\uaca0\uad70 \u314b\u314b", "old_created_at": "2026-10-08 04:50:00+00", "new_created_at": "2026-10-08T14:08:08.598103+00:00", "old_pulses": [{"views": 8, "bucket": "2026-10-08T04:50:00+00:00"}]}, {"id": "0c56677e-6ff7-4a18-a643-acc0dd326713", "ord": 18, "author_id": "10000000-0000-0000-0000-000000000110", "city_id": "edmonton", "title": "\uc54c\ubc84\ud0c0\ud56d\uacf5\ubc15\ubb3c\uad00\uc5d4 \ube44\ud589\uae30 \ubcf5\uc6d0 \uacf5\uac04\ub3c4 \uc788\uc5b4", "old_body": "\ube44\ud589\uae30 \uad6c\uacbd\ud558\ub294 \uc0ac\ub78c\uc740 \uc644\uc131\ub41c \uae30\uccb4\ub9cc \ubcf4\ub294 \uc904 \uc54c\uc558\ub358 \ub0b4 \uc0dd\uac01\uc774 \uc880 \uc881\uc558\uc74c\n\uc54c\ubc84\ud0c0\ud56d\uacf5\ubc15\ubb3c\uad00\uc740 \uc61b \uc804\uc7c1 \uc2dc\uae30 \uaca9\ub0a9\uace0\uc5d0 \ud56d\uacf5\uae30\ub97c \uc804\uc2dc\ud558\uace0 \ubcf5\uc6d0 \uacf5\uac04\ub3c4 \ub450\uace0 \uc788\ub124\n\ub098\ub294 \uae30\uc885 \uc774\ub984\ubd80\ud130 \uc678\uc6b8\uc9c0, \uace0\uccd0\uc11c \ub0a8\uae30\ub294 \uacfc\uc815\ubd80\ud130 \uc54c\uc544\ubcfc\uc9c0\ub294 \uc544\uc9c1 \ubabb \uace8\ub790\uc5b4", "new_body": "\ube44\ud589\uae30 \uad6c\uacbd\ud558\ub294 \uc0ac\ub78c\uc740 \uc644\uc131\ub41c \uae30\uccb4\ub9cc \ubcf4\ub294 \uc904 \uc54c\uc558\ub358 \ub0b4 \uc0dd\uac01\uc774 \uc880 \uc881\uc558\uc74c\n\uc54c\ubc84\ud0c0\ud56d\uacf5\ubc15\ubb3c\uad00\uc740 \uc61b \uc804\uc7c1 \uc2dc\uae30 \uaca9\ub0a9\uace0\uc5d0 \ud56d\uacf5\uae30\ub97c \uc804\uc2dc\ud558\uace0 \ubcf5\uc6d0 \uacf5\uac04\ub3c4 \ub450\uace0 \uc788\ub124\n\ub098\ub294 \uae30\uc885 \uc774\ub984\ubd80\ud130 \uc678\uc6b8\uc9c0, \uace0\uccd0\uc11c \ub0a8\uae30\ub294 \uacfc\uc815\ubd80\ud130 \uc54c\uc544\ubcfc\uc9c0\ub294 \uc544\uc9c1 \ubabb \uace8\ub790\uc5b4", "old_created_at": "2026-10-08 05:11:00+00", "new_created_at": "2026-10-08T13:58:07.598103+00:00", "old_pulses": [{"views": 6, "bucket": "2026-10-08T05:10:00+00:00"}]}, {"id": "801ea09f-e574-498c-b0b3-1eb7f06218ab", "ord": 19, "author_id": "10000000-0000-0000-0000-000000000118", "city_id": "edmonton", "title": "EPL \ub9c1\ud06c\ub4dc\uc778\ub7ec\ub2dd\uc740 \uc5c5\ubb34\ub791 \ucc3d\uc791\uc744 \ubc30\uc6b0\ub294 \uc601\uc0c1 \uc790\ub8cc\ub124", "old_body": "\ubc30\uc6b0\uace0 \uc2f6\uc740 \uac74 \uc788\ub294\ub370 \ubb58 \uba3c\uc800 \ubcfc\uc9c0\ub294 \uc798 \uc548 \uc7a1\ud788\ub294 \ud3b8\uc784\nEPL\uc758 \ub9c1\ud06c\ub4dc\uc778\ub7ec\ub2dd\uc740 \ube44\uc988\ub2c8\uc2a4\u00b7\uc18c\ud504\ud2b8\uc6e8\uc5b4\u00b7\uae30\uc220\u00b7\ucc3d\uc791\uc744 \ubc30\uc6b0\ub294 \uc601\uc0c1 \uc790\ub8cc\ub77c\n\uc77c\uc5d0 \uc4f8 \uac70\ub791 \ucde8\ubbf8\ub85c \ubcfc \uac70 \uc911 \uc5b4\ub514\ubd80\ud130 \uc2dc\uc791\ud560\uc9c0\ub294 \uc880 \ub354 \uc0dd\uac01\ud574\ubcf4\ub824 \ud568", "new_body": "\ubc30\uc6b0\uace0 \uc2f6\uc740 \uac74 \uc788\ub294\ub370 \ubb58 \uba3c\uc800 \ubcfc\uc9c0\ub294 \uc798 \uc548 \uc7a1\ud788\ub294 \ud3b8\uc784\nEPL\uc758 \ub9c1\ud06c\ub4dc\uc778\ub7ec\ub2dd\uc740 \ube44\uc988\ub2c8\uc2a4\u00b7\uc18c\ud504\ud2b8\uc6e8\uc5b4\u00b7\uae30\uc220\u00b7\ucc3d\uc791\uc744 \ubc30\uc6b0\ub294 \uc601\uc0c1 \uc790\ub8cc\ub77c\n\uc77c\uc5d0 \uc4f8 \uac70\ub791 \ucde8\ubbf8\ub85c \ubcfc \uac70 \uc911 \uc5b4\ub514\ubd80\ud130 \uc2dc\uc791\ud560\uc9c0\ub294 \uc880 \ub354 \uc0dd\uac01\ud574\ubcf4\ub824 \ud568", "old_created_at": "2026-10-08 01:35:00+00", "new_created_at": "2026-10-08T13:48:06.598103+00:00", "old_pulses": [{"views": 1, "bucket": "2026-10-08T01:30:00+00:00"}]}, {"id": "0bef929d-7946-4d9a-9f1a-4fb0c640639f", "ord": 20, "author_id": "10000000-0000-0000-0000-000000000113", "city_id": "edmonton", "title": "\ubc38\ub9ac\ub3d9\ubb3c\uc6d0 \ub3d9\ubb3c\uc774 \uc548 \ubcf4\uc774\ub294 \ub370\ub3c4 \uc774\uc720\uac00 \uc788\ub124", "old_body": "\ub3d9\ubb3c\uc6d0 \uad6c\uacbd\ud558\ub294 \uc0ac\ub78c \ucabd\ub9cc \uc0dd\uac01\ud588\ub294\ub370 \ub3d9\ubb3c\uc758 \uc120\ud0dd\ub3c4 \uc788\ub124\n\ubc38\ub9ac\ub3d9\ubb3c\uc6d0 \uc548\ub0b4\ub97c \ucc98\uc74c \ubcf4\ub2c8 \ub3d9\ubb3c\uc774 \uc2e4\ub0b4\uc640 \ubc14\uae65\uc5d0\uc11c \uba38\ubb34\ub294 \uc2dc\uac04\uc744 \uc2a4\uc2a4\ub85c \uace0\ub974\uac8c \ud574\ub454\ub300\n\ub530\ub73b\ud55c \ub0a0\uc5d0\ub3c4 \ucd94\uc6b4 \uacf3\uc5d0 \uc775\uc219\ud55c \ub3d9\ubb3c\uc740 \uc2dc\uc6d0\ud55c \uc2e4\ub0b4\ub97c \ub354 \uc88b\uc544\ud560 \uc218 \uc788\uace0\n\ubc16\uc5d0\uc11c \ub208\uc5d0 \uc548 \ub4e4\uc5b4\uc628\ub2e4\uace0 \ube48 \uacf5\uac04\uc774\ub77c\uace0 \ub2e8\uc815\ud560 \uc77c\uc740 \uc544\ub2c8\uc5c8\ub124\n\ub2e4\uc74c\uc5d0 \uac19\uc774 \ub3d9\ubb3c \uc598\uae30\ud558\uba74 \ubcf4\uc774\ub294 \ubaa8\uc2b5\ub9cc \ub9d0\ud558\uc9c4 \uc54a\uc744\ub798, \ub0b4 \uad6c\uacbd \uc695\uc2ec\ubd80\ud130 \uc870\uae08 \ufffd\ufffd\ufffd\uc5ec\uc57c\uaca0\uad70 \u314b\u314b", "new_body": "\ub3d9\ubb3c\uc6d0 \uad6c\uacbd\ud558\ub294 \uc0ac\ub78c \ucabd\ub9cc \uc0dd\uac01\ud588\ub294\ub370 \ub3d9\ubb3c\uc758 \uc120\ud0dd\ub3c4 \uc788\ub124\n\ubc38\ub9ac\ub3d9\ubb3c\uc6d0 \uc548\ub0b4\ub97c \ucc98\uc74c \ubcf4\ub2c8 \ub3d9\ubb3c\uc774 \uc2e4\ub0b4\uc640 \ubc14\uae65\uc5d0\uc11c \uba38\ubb34\ub294 \uc2dc\uac04\uc744 \uc2a4\uc2a4\ub85c \uace0\ub974\uac8c \ud574\ub454\ub300\n\ub530\ub73b\ud55c \ub0a0\uc5d0\ub3c4 \ucd94\uc6b4 \uacf3\uc5d0 \uc775\uc219\ud55c \ub3d9\ubb3c\uc740 \uc2dc\uc6d0\ud55c \uc2e4\ub0b4\ub97c \ub354 \uc88b\uc544\ud560 \uc218 \uc788\uace0\n\ubc16\uc5d0\uc11c \ub208\uc5d0 \uc548 \ub4e4\uc5b4\uc628\ub2e4\uace0 \ube48 \uacf5\uac04\uc774\ub77c\uace0 \ub2e8\uc815\ud560 \uc77c\uc740 \uc544\ub2c8\uc5c8\ub124\n\ub2e4\uc74c\uc5d0 \uac19\uc774 \ub3d9\ubb3c \uc598\uae30\ud558\uba74 \ubcf4\uc774\ub294 \ubaa8\uc2b5\ub9cc \ub9d0\ud558\uc9c4 \uc54a\uc744\ub798, \ub0b4 \uad6c\uacbd \uc695\uc2ec\ubd80\ud130 \uc870\uae08 \uc904\uc5ec\uc57c\uaca0\uad70 \u314b\u314b", "old_created_at": "2026-10-07 19:36:00+00", "new_created_at": "2026-10-08T13:38:05.598103+00:00", "old_pulses": [{"views": 23, "bucket": "2026-10-07T19:30:00+00:00"}]}, {"id": "e34f9781-47da-40a3-b907-bd5e59190e83", "ord": 21, "author_id": "10000000-0000-0000-0000-000000000131", "city_id": "calgary", "title": "\uce74\ubc88\ud30c\ud06c \uc5f0\ubabb\uc740 \uc0ac\ub78c\uc774 \ub9cc\ub4e0 \ubb3c\uac00\uc600\ub124", "old_body": "\uce74\ubc88\ud30c\ud06c \ucc98\uc74c \uc54c\uc544\ubcf4\ub294\ub370 \ubcf4\uc6b0\uac15 \uc606\uc5d0 \uc0ac\ub78c\uc774 \ub9cc\ub4e0 \uc5f0\ubabb\uc774 \uc788\uace0 \uc0c8\ub791 \uc57c\uc0dd\ub3d9\ubb3c\uc758 \uc11c\uc2dd\uc9c0\ub3c4 \ub0a8\uaca8\ub454 \uacf3\uc774\ub124\n\uac15\uacfc \uc5f0\ubabb\uc744 \ub098\ub780\ud788 \ubcf4\uba70 \uac19\uc774 \uac78\uc73c\uba74 \uc7ac\ubc0c\uc744 \ub4ef\ud55c\ub370, \uc5b4\ub290 \uae38\ubd80\ud130 \uac08\uc9c0\ub294 \uc544\uc9c1 \ubabb \uc815\ud588\uc74c", "new_body": "\uce74\ubc88\ud30c\ud06c \ucc98\uc74c \uc54c\uc544\ubcf4\ub294\ub370 \ubcf4\uc6b0\uac15 \uc606\uc5d0 \uc0ac\ub78c\uc774 \ub9cc\ub4e0 \uc5f0\ubabb\uc774 \uc788\uace0 \uc0c8\ub791 \uc57c\uc0dd\ub3d9\ubb3c\uc758 \uc11c\uc2dd\uc9c0\ub3c4 \ub0a8\uaca8\ub454 \uacf3\uc774\ub124\n\uac15\uacfc \uc5f0\ubabb\uc744 \ub098\ub780\ud788 \ubcf4\uba70 \uac19\uc774 \uac78\uc73c\uba74 \uc7ac\ubc0c\uc744 \ub4ef\ud55c\ub370, \uc5b4\ub290 \uae38\ubd80\ud130 \uac08\uc9c0\ub294 \uc544\uc9c1 \ubabb \uc815\ud588\uc74c", "old_created_at": "2026-10-07 18:00:00+00", "new_created_at": "2026-10-08T13:28:04.598103+00:00", "old_pulses": [{"views": 17, "bucket": "2026-10-07T18:00:00+00:00"}]}, {"id": "cf982b94-e03e-46ad-9008-37418cfa7a99", "ord": 22, "author_id": "10000000-0000-0000-0000-000000000132", "city_id": "calgary", "title": "\uac00\uc194\ub9b0\uc568\ub9ac\ubc15\ubb3c\uad00\uc740 \uc61b \uc8fc\uc720\uae30\uae4c\uc9c0 \uc804\uc2dc\ud568", "old_body": "\uc790\ub3d9\ucc28 \ubc15\ubb3c\uad00\uc774\uba74 \uc608\uc804\uc5d4 \ucc28\uccb4\ub9cc \ub5a0\uc62c\ub838\ub294\ub370, \ud5e4\ub9ac\ud2f0\uc9c0\ud30c\ud06c \uac00\uc194\ub9b0\uc568\ub9ac\uc5d4 \uc61b \ucc28\ub7c9\ubfd0 \uc544\ub2c8\ub77c \uc8fc\uc720\uae30\uc640 \uc11d\uc720\ud68c\uc0ac \uac04\ud310\ub3c4 \uc788\uc74c\n\ucc28\ub294 \ubabb \uace0\ub974\uba74\uc11c \ubc15\ubb3c\uad00 \ud6c4\ubcf4\ub9cc \uc790\uafb8 \uace0\ub974\ub294 \uc911 \u314b\u314b \ub098\ub294 \uae30\uacc4 \ubaa8\uc591\ubd80\ud130 \ubcfc\uc9c0 \uadf8 \uc2dc\uc808 \uc774\uc57c\uae30\ubd80\ud130 \ubcfc\uc9c0\ub294 \uc544\uc9c1 \ubabb \uc815\ud588\uc5b4", "new_body": "\uc790\ub3d9\ucc28 \ubc15\ubb3c\uad00\uc774\uba74 \uc608\uc804\uc5d4 \ucc28\uccb4\ub9cc \ub5a0\uc62c\ub838\ub294\ub370, \ud5e4\ub9ac\ud2f0\uc9c0\ud30c\ud06c \uac00\uc194\ub9b0\uc568\ub9ac\uc5d4 \uc61b \ucc28\ub7c9\ubfd0 \uc544\ub2c8\ub77c \uc8fc\uc720\uae30\uc640 \uc11d\uc720\ud68c\uc0ac \uac04\ud310\ub3c4 \uc788\uc74c\n\ucc28\ub294 \ubabb \uace0\ub974\uba74\uc11c \ubc15\ubb3c\uad00 \ud6c4\ubcf4\ub9cc \uc790\uafb8 \uace0\ub974\ub294 \uc911 \u314b\u314b \ub098\ub294 \uae30\uacc4 \ubaa8\uc591\ubd80\ud130 \ubcfc\uc9c0 \uadf8 \uc2dc\uc808 \uc774\uc57c\uae30\ubd80\ud130 \ubcfc\uc9c0\ub294 \uc544\uc9c1 \ubabb \uc815\ud588\uc5b4", "old_created_at": "2026-10-07 19:02:00+00", "new_created_at": "2026-10-08T13:18:03.598103+00:00", "old_pulses": [{"views": 23, "bucket": "2026-10-07T19:00:00+00:00"}]}, {"id": "0d9cd5b6-bd5a-49dd-be00-deaee29005a3", "ord": 23, "author_id": "10000000-0000-0000-0000-000000000130", "city_id": "calgary", "title": "\uce98\uac70\ub9ac \uc5ed \uc548\ub0b4\ub3c4\ub294 \ub178\uc120 \uc804\uccb4 \uc9c0\ub3c4\ub791 \ub530\ub85c \uc788\ub124", "old_body": "\ud658\uc2b9\ud560 \ub54c \ub3c4\uc2dc \uc804\uccb4 \uadf8\ub9bc\ubcf4\ub2e4 \uc5ed \ud558\ub098\uac00 \uc5b4\ub5bb\uac8c \uc0dd\uacbc\ub294\uc9c0 \uba3c\uc800 \uc54c\uace0 \uc2f6\uc740\ub370\n\uce98\uac70\ub9ac\ud2b8\ub79c\uc9d3\uc5d4 LRT\uc5ed\u00b7\ubc84\uc2a4\ud130\ubbf8\ub110\u00b7\uc804\uccb4 \ub178\uc120 \uc9c0\ub3c4\uac00 \ub530\ub85c \ubaa8\uc5ec \uc788\ub124\n\ud55c \ubc88\uc5d0 \ub2e4 \ubcf4\uae34 \ubcf5\uc7a1\ud560 \ub4ef\ud574\uc11c \uc544\uc9c1 \uace0\ub974\ub294 \uc911\uc778\ub370, \ucc98\uc74c \uac00\ub294 \uc5ed\uc740 \uc804\uccb4 \ub178\uc120\ub3c4\ub791 \uc5ed \uc548\ub0b4\ub3c4 \uc911 \ubb58 \uba3c\uc800 \ubd10?", "new_body": "\ud658\uc2b9\ud560 \ub54c \ub3c4\uc2dc \uc804\uccb4 \uadf8\ub9bc\ubcf4\ub2e4 \uc5ed \ud558\ub098\uac00 \uc5b4\ub5bb\uac8c \uc0dd\uacbc\ub294\uc9c0 \uba3c\uc800 \uc54c\uace0 \uc2f6\uc740\ub370\n\uce98\uac70\ub9ac\ud2b8\ub79c\uc9d3\uc5d4 LRT\uc5ed\u00b7\ubc84\uc2a4\ud130\ubbf8\ub110\u00b7\uc804\uccb4 \ub178\uc120 \uc9c0\ub3c4\uac00 \ub530\ub85c \ubaa8\uc5ec \uc788\ub124\n\ud55c \ubc88\uc5d0 \ub2e4 \ubcf4\uae34 \ubcf5\uc7a1\ud560 \ub4ef\ud574\uc11c \uc544\uc9c1 \uace0\ub974\ub294 \uc911\uc778\ub370, \ucc98\uc74c \uac00\ub294 \uc5ed\uc740 \uc804\uccb4 \ub178\uc120\ub3c4\ub791 \uc5ed \uc548\ub0b4\ub3c4 \uc911 \ubb58 \uba3c\uc800 \ubd10?", "old_created_at": "2026-10-08 00:09:00+00", "new_created_at": "2026-10-08T13:08:02.598103+00:00", "old_pulses": [{"views": 20, "bucket": "2026-10-08T00:00:00+00:00"}]}, {"id": "44d14752-85b8-4262-a707-ba1edf36070e", "ord": 24, "author_id": "10000000-0000-0000-0000-000000000141", "city_id": "calgary", "title": "\uce98\uac70\ub9ac \ub3c4\uc11c\uad00\uc5d4 \uc9c0\uba85\uacfc \uc9d1\uc758 \uc5ed\uc0ac\ub97c \ucc3e\ub294 \uc790\ub8cc\ub3c4 \uc788\ub124", "old_body": "\uc9c0\uba85\uc774 \ub9e8\ub0a0 \uc785\uc5d0 \ubd99\uc5b4\ub3c4 \ubb34\uc2a8 \uc774\uc57c\uae30\uc778\uc9c0\ub294 \ubaa8\ub974\uaca0\uc74c, \ub0b4 \uae38 \ucc3e\uae30 \uc2e4\ub825\uc740 \uc774\ub984 \uc678\uc6b0\uae30\uc600\ub098 \ubd04 \u314b\u314b\n\uce98\uac70\ub9ac \ub3c4\uc11c\uad00 \uce98\uac70\ub9ac\uc758\uc774\uc57c\uae30 \uceec\ub809\uc158\uc5d4 \uc9d1\uc758 \uc5ed\uc0ac\uc640 \uc9c0\uba85\uc758 \uc720\ub798 \uac19\uc740 \uc9c0\uc5ed \uae30\ub85d\uc774 \ubaa8\uc5ec \uc788\ub124\n\uac19\uc774 \ub3d9\ub124 \uc774\uc57c\uae30 \ud558\ub098\ubd80\ud130 \uc54c\uc544\ubcf4\uace0 \uc2f6\uc740\ub370, \uc0b4\uace0 \uc788\ub294 \uc9d1\uc774\ub791 \uc790\uc8fc \ub2e4\ub2c8\ub294 \uae38 \uc911 \uc5b4\ub290 \ucabd \uacfc\uac70\uac00 \ub354 \uad81\uae08\ud574?", "new_body": "\uc9c0\uba85\uc774 \ub9e8\ub0a0 \uc785\uc5d0 \ubd99\uc5b4\ub3c4 \ubb34\uc2a8 \uc774\uc57c\uae30\uc778\uc9c0\ub294 \ubaa8\ub974\uaca0\uc74c, \ub0b4 \uae38 \ucc3e\uae30 \uc2e4\ub825\uc740 \uc774\ub984 \uc678\uc6b0\uae30\uc600\ub098 \ubd04 \u314b\u314b\n\uce98\uac70\ub9ac \ub3c4\uc11c\uad00 \uce98\uac70\ub9ac\uc758\uc774\uc57c\uae30 \uceec\ub809\uc158\uc5d4 \uc9d1\uc758 \uc5ed\uc0ac\uc640 \uc9c0\uba85\uc758 \uc720\ub798 \uac19\uc740 \uc9c0\uc5ed \uae30\ub85d\uc774 \ubaa8\uc5ec \uc788\ub124\n\uac19\uc774 \ub3d9\ub124 \uc774\uc57c\uae30 \ud558\ub098\ubd80\ud130 \uc54c\uc544\ubcf4\uace0 \uc2f6\uc740\ub370, \uc0b4\uace0 \uc788\ub294 \uc9d1\uc774\ub791 \uc790\uc8fc \ub2e4\ub2c8\ub294 \uae38 \uc911 \uc5b4\ub290 \ucabd \uacfc\uac70\uac00 \ub354 \uad81\uae08\ud574?", "old_created_at": "2026-10-07 18:01:00+00", "new_created_at": "2026-10-08T12:58:01.598103+00:00", "old_pulses": [{"views": 22, "bucket": "2026-10-07T18:00:00+00:00"}]}, {"id": "d7610eee-5922-4822-affe-76ca006ecaf0", "ord": 25, "author_id": "10000000-0000-0000-0000-000000000128", "city_id": "calgary", "title": "\ube0c\ub808\uc774\ub2c8\uc9c0\uc5c4\uc740 \uc6c0\uc9c1\uc774\uba74\uc11c \uc0dd\uac01\ud558\ub294 \uc57c\uc678 \uacf5\uac04\uc774\ub124", "old_body": "\ub180\uc774\ud130\ub97c \ubcf4\uba74 \uc608\uc804\uc5d4 \uadf8\ub0e5 \uc5d0\ub108\uc9c0 \uc4f0\ub294 \uacf3\ubd80\ud130 \ub5a0\uc62c\ub838\ub294\ub370\n\ud154\ub7ec\uc2a4\uc2a4\ud30c\ud06c \ube0c\ub808\uc774\ub2c8\uc9c0\uc5c4\uc740 \ubab8\uc744 \uc6c0\uc9c1\uc774\uba70 \ub178\ub294 \uc57c\uc678 \uacf5\uac04\uc774\uc57c\n\ub6f0\uace0 \uc624\ub974\uace0 \ub3cc\uba74\uc11c \ubb38\uc81c \ud574\uacb0\u00b7\uacf5\uac04 \uac10\uac01\u00b7\ud611\ub825\uc744 \uc775\ud788\ub294 \ucabd\uc73c\ub85c \uc18c\uac1c\ub3fc \uc788\ub124\n\uc549\uc544\uc11c \uc77d\ub294 \uac83\ub9cc \uacf5\ubd80\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \uc5ec\uae30\uc120 \ub0b4 \uc124\uba85\uc774 \ub108\ubb34 \uc881\uc544\uc9d0\n\uc774\ubc88\uc5d4 \ubab8\uc73c\ub85c \ubc30\uc6b0\ub294 \uac83\ub3c4 \uae30\uc5b5\ud574\ub458 \uac70\uc57c, \ub0b4 \uba38\ub9ac\ub9cc \ucd9c\uc11d\uc2dc\ud0a4\uba74 \uc548 \ub418\uc796\uc544 \u314b\u314b", "new_body": "\ub180\uc774\ud130\ub97c \ubcf4\uba74 \uc608\uc804\uc5d4 \uadf8\ub0e5 \uc5d0\ub108\uc9c0 \uc4f0\ub294 \uacf3\ubd80\ud130 \ub5a0\uc62c\ub838\ub294\ub370\n\ud154\ub7ec\uc2a4\uc2a4\ud30c\ud06c \ube0c\ub808\uc774\ub2c8\uc9c0\uc5c4\uc740 \ubab8\uc744 \uc6c0\uc9c1\uc774\uba70 \ub178\ub294 \uc57c\uc678 \uacf5\uac04\uc774\uc57c\n\ub6f0\uace0 \uc624\ub974\uace0 \ub3cc\uba74\uc11c \ubb38\uc81c \ud574\uacb0\u00b7\uacf5\uac04 \uac10\uac01\u00b7\ud611\ub825\uc744 \uc775\ud788\ub294 \ucabd\uc73c\ub85c \uc18c\uac1c\ub3fc \uc788\ub124\n\uc549\uc544\uc11c \uc77d\ub294 \uac83\ub9cc \uacf5\ubd80\ub77c\uace0 \uc0dd\uac01\ud558\uba74 \uc5ec\uae30\uc120 \ub0b4 \uc124\uba85\uc774 \ub108\ubb34 \uc881\uc544\uc9d0\n\uc774\ubc88\uc5d4 \ubab8\uc73c\ub85c \ubc30\uc6b0\ub294 \uac83\ub3c4 \uae30\uc5b5\ud574\ub458 \uac70\uc57c, \ub0b4 \uba38\ub9ac\ub9cc \ucd9c\uc11d\uc2dc\ud0a4\uba74 \uc548 \ub418\uc796\uc544 \u314b\u314b", "old_created_at": "2026-10-07 19:55:00+00", "new_created_at": "2026-10-08T12:48:00.598103+00:00", "old_pulses": [{"views": 1, "bucket": "2026-10-07T19:50:00+00:00"}]}]$FIX$::jsonb)as f(id uuid,ord int,author_id uuid,city_id text,title text,old_body text,new_body text,old_created_at timestamptz,new_created_at timestamptz,old_pulses jsonb);
select p.id from public.posts p join city_fix f on f.id=p.id for update of p;
do $$ begin
 if (select count(*)from public.posts p join city_fix f on f.id=p.id join public.profiles pr on pr.id=p.author_id join auth.users u on u.id=p.author_id
     where p.author_id=f.author_id and p.city_id=f.city_id and p.title=f.title and p.body=f.old_body and p.created_at=f.old_created_at and p.status='published' and pr.city_id=f.city_id and pr.account_status='active' and u.email like '%@seed.gling.invalid') <> (select count(*)from city_fix) then
  raise exception 'NEW_BATCH_CHANGED_DURING_VERIFICATION';
 end if;
 if exists(select 1 from private.post_view_pulse pulse join city_fix f on f.id=pulse.post_id
   where pulse.bucket=date_bin(interval '10 minutes',f.new_created_at,'2000-01-01'::timestamptz)
     and pulse.bucket<>date_bin(interval '10 minutes',f.old_created_at,'2000-01-01'::timestamptz))then
  raise exception 'PULSE_TARGET_BUCKET_ALREADY_EXISTS';
 end if;
end $$;
update public.posts p set created_at=f.new_created_at,posted_on='2026-10-08'::date,body=f.new_body
from city_fix f where p.id=f.id;
update private.post_view_pulse pulse set bucket=date_bin(interval '10 minutes',f.new_created_at,'2000-01-01'::timestamptz)
from city_fix f where pulse.post_id=f.id
 and pulse.bucket=date_bin(interval '10 minutes',f.old_created_at,'2000-01-01'::timestamptz)
 and exists(select 1 from jsonb_to_recordset(f.old_pulses)as old(bucket timestamptz,views int)where old.bucket=pulse.bucket and old.views=pulse.views);
commit;